const GOOD_GOV_ROTATION_STORAGE_KEY = 'sobkru:a3-good-gov-exam-used-question-ids:v1';

const shuffleItems = <T,>(items: T[]): T[] => {
  const shuffled = [...items];

  for (let index = shuffled.length - 1; index > 0; index -= 1) {
    const randomIndex = Math.floor(Math.random() * (index + 1));
    [shuffled[index], shuffled[randomIndex]] = [shuffled[randomIndex], shuffled[index]];
  }

  return shuffled;
};

export const PART_A3_GOOD_GOV_QUESTIONS: GoodGovQuestion[] = RAW_A3_SEEDS.map(
  ([part, subject, question, answer, wrongA, wrongB, wrongC, explanation], index) => ({
    id: 3001 + index,
    part,
    subject,
    question,
    options: [answer, wrongA, wrongB, wrongC],
    correctAnswer: 0,
    explanation,
  }),
);

const readUsedQuestionIds = (key: string): number[] => {
  if (typeof window === 'undefined') return [];

  try {
    const raw = window.localStorage.getItem(key);
    const parsed = raw ? JSON.parse(raw) : [];
    return Array.isArray(parsed) ? parsed.filter((id): id is number => typeof id === 'number') : [];
  } catch {
    return [];
  }
};

const writeUsedQuestionIds = (key: string, ids: number[]) => {
  if (typeof window === 'undefined') return;

  try {
    window.localStorage.setItem(key, JSON.stringify(ids));
  } catch {
    // Keep the exam usable even if localStorage is unavailable.
  }
};

const shuffleQuestionOptions = (question: GoodGovQuestion): Question => {
  const optionPairs = question.options.map((option, optionIndex) => ({
    option,
    isCorrect: optionIndex === question.correctAnswer,
  }));
  const shuffledPairs = shuffleItems(optionPairs);

  return {
    ...question,
    options: shuffledPairs.map((pair) => pair.option),
    correctAnswer: shuffledPairs.findIndex((pair) => pair.isCorrect),
  };
};

const pickRotatingQuestions = (
  pool: GoodGovQuestion[],
  count: number,
  key: string,
): GoodGovQuestion[] => {
  const safeCount = Math.min(count, pool.length);
  const questionIds = new Set(pool.map((question) => question.id));
  const usedIds = new Set(readUsedQuestionIds(key).filter((id) => questionIds.has(id)));
  let nextUsedIds = new Set(usedIds);
  let availableQuestions = pool.filter((question) => !usedIds.has(question.id));

  if (availableQuestions.length < safeCount) {
    availableQuestions = pool;
    nextUsedIds = new Set();
  }

  const selectedQuestions = shuffleItems(availableQuestions).slice(0, safeCount);
  selectedQuestions.forEach((question) => nextUsedIds.add(question.id));

  if (nextUsedIds.size >= pool.length) {
    writeUsedQuestionIds(key, selectedQuestions.map((question) => question.id));
  } else {
    writeUsedQuestionIds(key, [...nextUsedIds]);
  }

  return selectedQuestions;
};

const getPoolByPart = (part: GoodGovPart) =>
  PART_A3_GOOD_GOV_QUESTIONS.filter((question) => question.part === part);

export const getPartA3GoodGovExamQuestions = (
  count = PART_A3_GOOD_GOV_EXAM_META.questionCount,
): Question[] => {
  if (count !== PART_A3_GOOD_GOV_EXAM_META.questionCount) {
    return shuffleItems(PART_A3_GOOD_GOV_QUESTIONS)
      .slice(0, Math.min(count, PART_A3_GOOD_GOV_QUESTIONS.length))
      .map(shuffleQuestionOptions);
  }

  const selectedQuestions = (Object.keys(SECTION_PICK_COUNTS) as GoodGovPart[]).flatMap((part) =>
    pickRotatingQuestions(
      getPoolByPart(part),
      SECTION_PICK_COUNTS[part],
      `${GOOD_GOV_ROTATION_STORAGE_KEY}:${part}`,
    ),
  );

  return shuffleItems(selectedQuestions).map(shuffleQuestionOptions);
};
